			prev := bytes[i] - 1
			canRemove := false
			if i > 0 && bytes[i-1] == prev {
				canRemove = true
			}
			if i < len(bytes)-1 && bytes[i+1] == prev {
				canRemove = true
			}
			if canRemove {
				if bytes[i] > bestChar {
					bestChar = bytes[i]
					bestIdx = i
				}
			}
		}
		if bestIdx == -1 {
			break
		}
		// Remove the character at bestIdx
		bytes = append(bytes[:bestIdx], bytes[bestIdx+1:]...)
		count++
	}

	fmt.Println(count)
